#include <omp.h>
#include <cstddef>
#include <string>
#include <vector>

struct Book {
    std::string title;
    int pages;
};

size_t findLastShortBook(std::vector<Book> const& books) {
    const size_t n = books.size();
    size_t last_match_plus_one = 0;  // 0 means "not found"

    #pragma omp parallel for reduction(max:last_match_plus_one)
    for (size_t i = 0; i < n; ++i) {
        if (books[i].pages < 100) {
            const size_t candidate = i + 1;
            if (candidate > last_match_plus_one) {
                last_match_plus_one = candidate;
            }
        }
    }

    return (last_match_plus_one == 0) ? n : (last_match_plus_one - 1);
}
